files.bits.c:
#include <stdio.h>
int popcount(unsigned int x) {
    int count = 0;
    while (x) { count += x & 1; x >>= 1; }
    return count;
}
unsigned int reverse_bits(unsigned int x) {
    unsigned int r = 0;
    for (int i = 0; i < 32; i++) {
        r = (r << 1) | (x & 1);
        x >>= 1;
    }
    return r;
}
int main() {
    printf("pop(0xFF)=%d\n", popcount(0xFF));
    printf("pop(0xF0)=%d\n", popcount(0xF0));
    unsigned int rev = reverse_bits(0x80000001);
    printf("rev=%08x\n", rev);
    return 0;
}

