#include <stdio.h>
#include <stdarg.h>
int sum_all(int count, ...) {
    va_list ap;
    va_start(ap, count);
    int total = 0;
    for (int i = 0; i < count; i++) {
        total += va_arg(ap, int);
    }
    va_end(ap);
    return total;
}
double avg_all(int count, ...) {
    va_list ap;
    va_start(ap, count);
    double total = 0;
    for (int i = 0; i < count; i++) {
        total += va_arg(ap, double);
    }
    va_end(ap);
    return total / count;
}
int main() {
    printf("sum=%d\n", sum_all(5, 1, 2, 3, 4, 5));
    printf("avg=%.1f\n", avg_all(3, 1.0, 2.0, 3.0));
    return 0;
}

